from __future__ import annotations

import json
import logging
import uuid
from typing import Any, Mapping

_REDACTED = "[REDACTED]"
_REQUEST_ID_HEADERS: tuple[str, ...] = ("x-request-id", "x-correlation-id")
_SENSITIVE_KEY_FRAGMENTS: tuple[str, ...] = (
    "authorization",
    "token",
    "assertion",
    "credential",
    "secret",
    "password",
    "samlresponse",
    "id_token",
    "access_token",
    "refresh_token",
)


def redact_sensitive_data(value: Any) -> Any:
    """Recursively redact token-like and assertion-like material."""

    if isinstance(value, Mapping):
        redacted: dict[str, Any] = {}
        for key, item in value.items():
            normalized_key = str(key).lower().replace("-", "").replace("_", "")
            if any(fragment in normalized_key for fragment in _SENSITIVE_KEY_FRAGMENTS):
                redacted[str(key)] = _REDACTED
            else:
                redacted[str(key)] = redact_sensitive_data(item)
        return redacted

    if isinstance(value, tuple):
        return tuple(redact_sensitive_data(item) for item in value)

    if isinstance(value, list):
        return [redact_sensitive_data(item) for item in value]

    if isinstance(value, set):
        return {redact_sensitive_data(item) for item in value}

    return value


def correlation_id_from_headers(headers: Mapping[str, Any] | None = None) -> str:
    """Resolve a stable correlation identifier from request headers or generate one."""

    if headers is not None:
        for key in _REQUEST_ID_HEADERS:
            raw_value = headers.get(key)
            if raw_value is None:
                continue
            value = str(raw_value).strip()
            if value:
                return value
    return str(uuid.uuid4())


def log_auth_event(
    *,
    logger: logging.Logger | None,
    event: str,
    request_id: str | None = None,
    actor_id: str | None = None,
    outcome: str | None = None,
    details: Mapping[str, Any] | None = None,
) -> None:
    """Emit structured auth logs with minimal identifiers and redacted details."""

    payload: dict[str, Any] = {"event": event}
    if request_id:
        payload["request_id"] = request_id
    if actor_id:
        payload["actor_id"] = actor_id
    if outcome:
        payload["outcome"] = outcome
    if details:
        payload["details"] = redact_sensitive_data(details)

    active_logger = logger or logging.getLogger(__name__)
    active_logger.info(
        json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str),
    )
